/** Build identifier injected by Vite (`FLOURPRINT_BUILD`, `dev` locally). */
declare const __APP_BUILD__: string;
/** Short build name shown in the app bar (`FLOURPRINT_LABEL`, ADR 0016). */
declare const __APP_LABEL__: string;
/** `release`, `dev`, `preview` or `local` (`FLOURPRINT_CHANNEL`, ADR 0016). */
declare const __APP_CHANNEL__: string;
